input.command:
cd /workspace
duckdb -csv -c "
LOAD httpfs;
COPY (SELECT tier, count(*) n FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet') GROUP BY tier ORDER BY tier) TO 'answers/q02.csv' (HEADER);
COPY (SELECT municipio, count(*) n_parcels FROM read_parquet('work/parcels.parquet') GROUP BY 1 ORDER BY 1) TO 'answers/q06.csv' (HEADER);
"
echo "--- q02 ---"; cat answers/q02.csv; echo "--- q06 ---"; cat answers/q06.csv

cd /workspace
duckdb -c "
LOAD spatial;
SELECT ST_XMin(e) xmin, ST_YMin(e) ymin, ST_XMax(e) xmax, ST_YMax(e) ymax
FROM (SELECT ST_Extent(ST_Union_Agg(ST_GeomFromWKB(geom_wkb))) e FROM read_parquet('work/parcels.parquet'));
" 2>&1 | tail -8

cd /workspace
duckdb -c "
LOAD spatial;
SET geometry_always_xy=true;
CREATE TEMP TABLE f AS SELECT Id, ST_GeomFromWKB(geom_wkb) g FROM read_parquet('work/fields.parquet') LIMIT 5;
SELECT Id,
  ST_Area_Spheroid(g)/10000 AS xy_true_ha,
  ST_Area(ST_Transform(g,'EPSG:4326','EPSG:5880'))/10000 AS proj5880_ha
FROM f;
" 2>&1 | grep -v -i 'axis\|latitude\|longitude\|geometry_always\|expected\|Please\|current default' | tail -12
echo "=== default axis order ==="
duckdb -c "
LOAD spatial;
CREATE TEMP TABLE f AS SELECT Id, ST_GeomFromWKB(geom_wkb) g FROM read_parquet('work/fields.parquet') LIMIT 5;
SELECT Id, ST_Area_Spheroid(g)/10000 AS default_ha FROM f;
" 2>&1 | grep -v -i 'axis\|latitude\|longitude\|geometry_always\|expected\|Please\|current default' | tail -12

